static uint8_t buf[N];
static volatile uint8_t head;
static volatile uint8_t tail;

void uart_isr(void) {
    uint8_t next = (head + 1) % N;
    if (next != tail) {       // not full
        buf[head] = UART->DR;
        head = next;          // publish after the data
    }
